-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — Jižní Čechy (CZ)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Zámek Hluboká a Vltavotýnsko
  delete from public.routes where name = 'Zámek Hluboká a Vltavotýnsko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Zámek Hluboká a Vltavotýnsko', 'Pohodový okruh z Českých Budějovic k nejromantičtějšímu zámku Čech a dál po pravém břehu Vltavy na sever. Silnice podél řeky přes Purkarec do Týna nad Vltavou se vlní mezi lesy a nabízí plynulé, nenáročné tempo — ideální první vyjížďka sezóny nebo podvečerní okruh. Po prohlídce hluboké bílé pohádky si dopřejte klid loveckého zámečku Ohrada a v Kolodějích nad Lužnicí barokní perlu Mitrowicz. Nejlépe od dubna do října; v létě počítejte kolem Hluboké s hustším provozem a cyklisty u řeky. Povrch je vesměs kvalitní, jen okreska přes Purkarec má pár záplatovaných úseků.', 'loop', 85, 150, 'easy',
     '[{"lat": 48.9745, "lng": 14.4743, "label": "Start: České Budějovice"}, {"lat": 49.0510, "lng": 14.4444, "label": "Hluboká nad Vltavou"}, {"lat": 49.1224, "lng": 14.4536, "label": "Purkarec"}, {"lat": 49.2235, "lng": 14.4208, "label": "Týn nad Vltavou"}, {"lat": 49.2110, "lng": 14.4670, "label": "Koloděje nad Lužnicí"}, {"lat": 48.9745, "lng": 14.4743, "label": "Cíl: České Budějovice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9745,14.4743&destination=48.9745,14.4743&travelmode=driving&waypoints=49.0510,14.4444%7C49.1224,14.4536%7C49.2235,14.4208%7C49.2110,14.4670', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hluboka%20castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hluboka%20castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Loveck%C3%BD%20z%C3%A1mek%20Ohrada%20-%20pr%C5%AF%C4%8Del%C3%AD.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%BDn%20nad%20Vltavou.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Mitrowicz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%20Samson-Brunnen%20159.jpg"}'::text[], '{"Zámek Hluboká nad Vltavou","Lovecký zámek Ohrada","Týn nad Vltavou – náměstí Míru","Zámek Mitrowicz (Koloděje nad Lužnicí)","Restaurace: Masné krámy (České Budějovice)"}'::text[], '{"CZ"}'::text[], false, 2010, 'approved');

  -- Perly Vltavy – Český Krumlov a Rožmberk
  delete from public.routes where name = 'Perly Vltavy – Český Krumlov a Rožmberk' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Perly Vltavy – Český Krumlov a Rožmberk', 'Nejkrásnější říční údolí jižních Čech v jednom okruhu: gotický klášter Zlatá Koruna, renesanční Český Krumlov zapsaný na seznamu UNESCO, hrad Rožmberk vysoko nad meandrem Vltavy a cisterciácký Vyšší Brod. Silnice číslo 160 z Krumlova na Rožmberk kopíruje řeku a patří k nejhezčím motorkářským úsekům v Čechách — plynulé zatáčky, minimum rovinek. Zpět se vracíte přes Kaplici po rychlejší sto padesát sedmičce. Nejlepší je všední den mimo hlavní sezónu, o prázdninách je Krumlov turisticky našlapaný a parkování chvíli zabere. Pozor na vodáky přebíhající u kempů podél řeky a na stín v údolí, kde silnice zjara pomalu osychá.', 'loop', 135, 210, 'medium',
     '[{"lat": 48.9745, "lng": 14.4743, "label": "Start: České Budějovice"}, {"lat": 48.8551, "lng": 14.3714, "label": "Zlatá Koruna"}, {"lat": 48.8127, "lng": 14.3149, "label": "Český Krumlov"}, {"lat": 48.6539, "lng": 14.3660, "label": "Rožmberk nad Vltavou"}, {"lat": 48.6157, "lng": 14.3110, "label": "Vyšší Brod"}, {"lat": 48.7387, "lng": 14.4956, "label": "Kaplice"}, {"lat": 48.9745, "lng": 14.4743, "label": "Cíl: České Budějovice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9745,14.4743&destination=48.9745,14.4743&travelmode=driving&waypoints=48.8551,14.3714%7C48.8127,14.3149%7C48.6539,14.3660%7C48.6157,14.3110%7C48.7387,14.4956', 'https://commons.wikimedia.org/wiki/Special:FilePath/St%C3%A1tn%C3%AD%20hrad%20a%20z%C3%A1mek%20%C4%8Cesk%C3%BD%20Krumlov.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20Zlat%C3%A1%20Koruna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/St%C3%A1tn%C3%AD%20hrad%20a%20z%C3%A1mek%20%C4%8Cesk%C3%BD%20Krumlov.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20%C4%8Cesk%C3%BD%20Krumlov%20in%202012.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20rozmberk.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20Vy%C5%A1%C5%A1%C3%AD%20Brod.JPG"}'::text[], '{"Klášter Zlatá Koruna","Státní hrad a zámek Český Krumlov","Restaurace: Krčma v Šatlavské ulici (Český Krumlov)","Hrad Rožmberk nad Vltavou","Klášter Vyšší Brod"}'::text[], '{"CZ"}'::text[], false, 2020, 'approved');

  -- Renesanční Kratochvíle a Zlatá stezka
  delete from public.routes where name = 'Renesanční Kratochvíle a Zlatá stezka' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Renesanční Kratochvíle a Zlatá stezka', 'Okruh Prácheňskem po stopách rožmberské renesance a středověké Zlaté stezky, po níž se ze Solné komory vozila sůl. Vodní zámek Kratochvíle je italská vila uprostřed jihočeských luk, poutní Lomec zase barokní klenot ukrytý v lesích. Okresky mezi Netolicemi, Bavorovem a Prachaticemi jsou úzké, zvlněné a téměř prázdné — přesně to, co motorkář hledá. Výšlap na zříceninu Helfenburk (20 minut pěšky z parkoviště) odmění kruhový rozhled z hradní věže. Jarní a podzimní jízdě sluší nejvíc; po dešti pozor na listí a štěrk v lesních zatáčkách.', 'loop', 120, 195, 'medium',
     '[{"lat": 48.9745, "lng": 14.4743, "label": "Start: České Budějovice"}, {"lat": 49.0637, "lng": 14.1701, "label": "Zámek Kratochvíle"}, {"lat": 49.1010, "lng": 14.2078, "label": "Lomec"}, {"lat": 49.1220, "lng": 14.0787, "label": "Bavorov"}, {"lat": 49.1367, "lng": 14.0064, "label": "Helfenburk"}, {"lat": 49.0119, "lng": 13.9975, "label": "Prachatice"}, {"lat": 48.9745, "lng": 14.4743, "label": "Cíl: České Budějovice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9745,14.4743&destination=48.9745,14.4743&travelmode=driving&waypoints=49.0637,14.1701%7C49.1010,14.2078%7C49.1220,14.0787%7C49.1367,14.0064%7C49.0119,13.9975', 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Kratochvile.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Kratochvile.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lomec%2C%20kostel%20Jm%C3%A9na%20Panny%20Marie.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bavorov%20z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Helfenburk%2C%20obytn%C3%A1%20v%C4%9B%C5%BE%2C%20vstupn%C3%AD%20%C4%8D%C3%A1st.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prachatice%2C%20Velk%C3%A9%20n%C3%A1m%C4%9Bst%C3%AD%20(1).jpg"}'::text[], '{"Zámek Kratochvíle","Poutní kostel Lomec","Bavorov – zámek a kostel","Zřícenina hradu Helfenburk u Bavorova","Prachatice – Velké náměstí"}'::text[], '{"CZ"}'::text[], false, 2030, 'approved');

  -- Okolo Lipna – jihočeské moře
  delete from public.routes where name = 'Okolo Lipna – jihočeské moře' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Okolo Lipna – jihočeské moře', 'Okruh kolem největší vodní plochy Česka: po pravém břehu přes hráz a Loučovice na Přední Výtoň, po levém zpět přes Frymburk a Horní Planou. Střídají se výhledy na hladinu, šumavské lesy a žulová skaliska Čertovy stěny, k tomu vyhlídková zřícenina Vítkův hrádek — nejvýše položený hrad v Čechách s výhledem až na Alpy. Silnice jsou dobře udržované a zatáčkovité, mezi Frymburkem a Černou v Pošumaví vedou přímo u vody. Ideální od května do října; o letních víkendech počítejte s rekreačním provozem a u Frymburka s frontou na přívoz. Ráno bývá nad hladinou mlha a chladno i v létě — vezměte vrstvu navíc.', 'loop', 130, 225, 'medium',
     '[{"lat": 48.8107, "lng": 14.3153, "label": "Start: Český Krumlov"}, {"lat": 48.6270, "lng": 14.2390, "label": "Lipno nad Vltavou – hráz"}, {"lat": 48.6210, "lng": 14.2860, "label": "Čertova stěna"}, {"lat": 48.6297, "lng": 14.1935, "label": "Svatý Tomáš – Vítkův hrádek"}, {"lat": 48.6592, "lng": 14.1657, "label": "Frymburk"}, {"lat": 48.7683, "lng": 14.0326, "label": "Horní Planá"}, {"lat": 48.7370, "lng": 14.1070, "label": "Černá v Pošumaví"}, {"lat": 48.8107, "lng": 14.3153, "label": "Cíl: Český Krumlov"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.8107,14.3153&destination=48.8107,14.3153&travelmode=driving&waypoints=48.6270,14.2390%7C48.6210,14.2860%7C48.6297,14.1935%7C48.6592,14.1657%7C48.7683,14.0326%7C48.7370,14.1070', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lipno%20nad%20Vltavou%2C%20p%C5%99ehradn%C3%AD%20hr%C3%A1z%2C%20p%C5%99ehrada.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lipno%20nad%20Vltavou%2C%20p%C5%99ehradn%C3%AD%20hr%C3%A1z%2C%20p%C5%99ehrada.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Certova-st%C4%9Bna-Vyhl%C3%ADdka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADtk%C5%AFv%20k%C3%A1men%2Cz%C5%99icenina.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Frymburk%2C%20p%C5%99%C3%ADvoz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/A%20Stifter-statue.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Frymburk%2C%20kostel%20a%20fara.jpg"}'::text[], '{"Hráz Lipna a vodní elektrárna","NPR Čertova stěna-Luč","Vítkův hrádek (Svatý Tomáš)","Frymburk a přívoz do Frýdavy","Horní Planá – rodiště Adalberta Stiftera","Restaurace: Hotel Maxant (Frymburk)"}'::text[], '{"CZ"}'::text[], false, 2040, 'approved');

  -- Přehrady Malše a Vltavy – Římov a Hněvkovice
  delete from public.routes where name = 'Přehrady Malše a Vltavy – Římov a Hněvkovice' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Přehrady Malše a Vltavy – Římov a Hněvkovice', 'Vodohospodářský okruh Budějovickem od pitné rezervy na Malši po vltavskou kaskádu u Temelína. Začíná se u římovské přehrady a barokní Lorety s pašijovou cestou, pokračuje přes rodiště Jana Žižky v Trocnově a končí u hněvkovické hráze, která napájí chladicí věže největší české elektrárny. Trasa vede po klidných okreskách mezi rybníky a lesy, bez náročných pasáží — vhodná i pro méně zkušené jezdce. Infocentrum Temelína v zámečku Vysoký Hrádek nabízí zdarma expozici i vyhlídku na věže. Jezdit se dá od jara do podzimu, provoz je slabý po celý rok.', 'loop', 140, 210, 'easy',
     '[{"lat": 48.9745, "lng": 14.4743, "label": "Start: České Budějovice"}, {"lat": 48.8486, "lng": 14.4897, "label": "Římov – přehrada"}, {"lat": 48.8980, "lng": 14.5990, "label": "Trocnov"}, {"lat": 49.1830, "lng": 14.4470, "label": "Hněvkovice – hráz"}, {"lat": 49.1770, "lng": 14.3690, "label": "Temelín – Vysoký Hrádek"}, {"lat": 48.9745, "lng": 14.4743, "label": "Cíl: České Budějovice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9745,14.4743&destination=48.9745,14.4743&travelmode=driving&waypoints=48.8486,14.4897%7C48.8980,14.5990%7C49.1830,14.4470%7C49.1770,14.3690', 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%98%C3%ADmov%2C%20vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%98%C3%ADmov%2C%20pohled%20k%20hr%C3%A1zi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%98%C3%ADmov%2C%20vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%98%C3%ADmov%2C%20pohled%20k%20hr%C3%A1zi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%98%C3%ADmov%2C%20Loreta%203.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jan%20%C5%BDi%C5%BEka%20z%20Trocnova%20(03).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Hn%C4%9Bvkovice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chlad%C3%ADc%C3%AD%20v%C4%9B%C5%BEe%20JETE.JPG"}'::text[], '{"Vodní nádrž Římov","Římov – Loreta a pašijová cesta","Trocnov – památník Jana Žižky","Vodní nádrž Hněvkovice – hráz","Infocentrum JE Temelín – zámeček Vysoký Hrádek"}'::text[], '{"CZ"}'::text[], false, 2050, 'approved');

  -- Blanský les a rozhledna Kleť
  delete from public.routes where name = 'Blanský les a rozhledna Kleť' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Blanský les a rozhledna Kleť', 'Kompaktní okruh chráněnou krajinnou oblastí Blanský les kolem nejstarší kamenné rozhledny v Čechách. Z Budějovic přes selské baroko Holašovic (UNESCO) do Křemžské kotliny, kde se nad krajinou zvedá tisícovka Kleť s rozhlednou z roku 1825 a hvězdárnou — nahoru vede sedačková lanovka z Krasetína nebo hodinová procházka. Na zpáteční cestě čeká tajemná zřícenina Dívčí Kámen nad soutokem Vltavy a Křemžského potoka. Okresky v kotlině jsou úzké, zvlněné a překvapivě zábavné, provoz minimální. Za jasného počasí je z Kleti vidět celý řetěz Alp — vyplatí se vyjet brzy ráno na podzim.', 'loop', 95, 180, 'medium',
     '[{"lat": 48.9745, "lng": 14.4743, "label": "Start: České Budějovice"}, {"lat": 48.9700, "lng": 14.2726, "label": "Holašovice"}, {"lat": 48.9053, "lng": 14.3057, "label": "Křemže"}, {"lat": 48.8800, "lng": 14.3050, "label": "Krasetín – lanovka na Kleť"}, {"lat": 48.8888, "lng": 14.3630, "label": "Dívčí Kámen"}, {"lat": 48.9745, "lng": 14.4743, "label": "Cíl: České Budějovice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9745,14.4743&destination=48.9745,14.4743&travelmode=driving&waypoints=48.9700,14.2726%7C48.9053,14.3057%7C48.8800,14.3050%7C48.8888,14.3630', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Kle%C5%A5%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hola%C5%A1ovice%20Historic%20Village-112772.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Kle%C5%A5%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kle%C5%A5%20lanovka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20D%C3%ADv%C4%8D%C3%AD%20K%C3%A1men%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kuklov%2C%20z%C5%99%C3%ADcenina%20kl%C3%A1%C5%A1tera.jpg"}'::text[], '{"Holašovice – selské baroko (UNESCO)","Rozhledna Kleť","Lanová dráha Krasetín–Kleť","Zřícenina hradu Dívčí Kámen","Kuklov – zřícenina kláštera"}'::text[], '{"CZ"}'::text[], false, 2060, 'approved');

  -- Rozhledny Píseckých hor
  delete from public.routes where name = 'Rozhledny Píseckých hor' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rozhledny Píseckých hor', 'Nenáročný okruh kolem zlatonosné Otavy a zalesněnými hřbety Píseckých hor za dvěma rozhlednami s výhledem od Šumavy po Brdy. Startuje se u nejstaršího kamenného mostu v Česku, pak lesními silničkami na věž Jarník a přes hřeben k rozhledně Velký Kamýk. Cestou zpět stojí za zastávku secesní areál Zemského hřebčince, technická i architektonická památka. Okresky v Píseckých horách jsou úzké a stinné, na jaře a po dešti počítejte s vlhkými úseky a jehličím ve stopě. Ideální polodenní vyjížďka, kterou zvládne i začátečník.', 'loop', 90, 165, 'easy',
     '[{"lat": 49.3088, "lng": 14.1469, "label": "Start: Písek – Kamenný most"}, {"lat": 49.3006, "lng": 14.1934, "label": "Rozhledna Jarník"}, {"lat": 49.2758, "lng": 14.2040, "label": "Velký Kamýk"}, {"lat": 49.2600, "lng": 14.1500, "label": "Smrkovice"}, {"lat": 49.3149, "lng": 14.1360, "label": "Zemský hřebčinec"}, {"lat": 49.3088, "lng": 14.1469, "label": "Cíl: Písek – Kamenný most"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3088,14.1469&destination=49.3088,14.1469&travelmode=driving&waypoints=49.3006,14.1934%7C49.2758,14.2040%7C49.2600,14.1500%7C49.3149,14.1360', 'https://commons.wikimedia.org/wiki/Special:FilePath/P%C3%ADsek%2C%20kamenn%C3%BD%20most.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/P%C3%ADsek%2C%20kamenn%C3%BD%20most.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Jarn%C3%ADk%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Velk%C3%BD%20Kam%C3%BDk.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zemsk%C3%BD%20h%C5%99eb%C4%8Dinec%20P%C3%ADsek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/P%C3%ADsek%2C%20the%20Stone%20Bridge-2.JPG"}'::text[], '{"Písek – Kamenný most","Rozhledna Jarník","Rozhledna Velký Kamýk","Zemský hřebčinec Písek","Restaurace: U Reinerů (Písek)"}'::text[], '{"CZ"}'::text[], false, 2070, 'approved');

  -- Novohradské hory a Terčino údolí
  delete from public.routes where name = 'Novohradské hory a Terčino údolí' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Novohradské hory a Terčino údolí', 'Nejtišší pohoří Čech: bývalé pohraniční pásmo, kam desítky let nesměl nikdo vkročit, dnes nabízí prázdné silnice, hluboké lesy a zaniklé vesnice. Okruh spojuje středověké Nové Hrady s romantickým Terčiným údolím, poutní Dobrou Vodu s rozhlednou na Kraví hoře a končí až u kostela zaniklé osady Pohoří na Šumavě na rakouské hranici. Silničky za Benešovem nad Černou jsou úzké, místy s horším povrchem, ale provoz se blíží nule — jen pozor na zvěř, hlavně za soumraku. Nejkrásněji je tu na přelomu září a října, kdy bučiny hrají barvami. Tankujte předem, benzínka je až v Kaplici nebo Trhových Svinech.', 'loop', 160, 255, 'medium',
     '[{"lat": 48.9745, "lng": 14.4743, "label": "Start: České Budějovice"}, {"lat": 48.7896, "lng": 14.7786, "label": "Nové Hrady"}, {"lat": 48.7830, "lng": 14.7560, "label": "Terčino údolí"}, {"lat": 48.7423, "lng": 14.7290, "label": "Dobrá Voda"}, {"lat": 48.7290, "lng": 14.6280, "label": "Benešov nad Černou"}, {"lat": 48.6000, "lng": 14.6940, "label": "Pohoří na Šumavě"}, {"lat": 48.7387, "lng": 14.4956, "label": "Kaplice"}, {"lat": 48.9745, "lng": 14.4743, "label": "Cíl: České Budějovice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9745,14.4743&destination=48.9745,14.4743&travelmode=driving&waypoints=48.7896,14.7786%7C48.7830,14.7560%7C48.7423,14.7290%7C48.7290,14.6280%7C48.6000,14.6940%7C48.7387,14.4956', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Nov%C3%A9%20Hrady.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Nov%C3%A9%20Hrady.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tercino-udoli-vodopad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20Hrady%2C%20%C3%9Adol%C3%AD%2C%20Cukn%C5%A1tejn%20(01).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dobr%C3%A1%20voda%20kostel%204.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Krav%C3%AD%20hora%20rozhledna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Poho%C5%99%C3%AD%20na%20%C5%A0umav%C4%9B.jpg"}'::text[], '{"Hrad Nové Hrady","Terčino údolí – umělý vodopád","Tvrz Cuknštejn","Dobrá Voda u Nových Hradů","Rozhledna Kraví hora","Pohoří na Šumavě – zaniklá osada"}'::text[], '{"CZ"}'::text[], false, 2080, 'approved');

  -- Šumavský Stožec a Schwarzenberský kanál
  delete from public.routes where name = 'Šumavský Stožec a Schwarzenberský kanál' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Šumavský Stožec a Schwarzenberský kanál', 'Jihovýchodní cíp Národního parku Šumava, kam většina návštěvníků nedojede: údolí Teplé Vltavy mezi Lenorou a Stožcem a technický zázrak osvícenství — Schwarzenberský plavební kanál, který přes rozvodí spojil Vltavu s Dunajem. Trasa vede po parkových silnicích mezi rašeliništi a horskými loukami, s odbočkou k Jelením Vrchům, kde kanál vtéká do portálu plavebního tunelu. Zastavíte u krytého dřevěného mostu v Lenoře, u vyhlídkové věže nad Soumarským rašeliništěm i u horské kaple nad Stožcem. Provoz je slabý, ale v NP platí přísné rychlostní limity a časté kontroly — jeďte v klidu a užívejte scenérii. Nejlepší od června do října, brzy zjara bývají silnice po zimě posypané štěrkem.', 'loop', 120, 210, 'medium',
     '[{"lat": 48.9090, "lng": 13.8870, "label": "Start: Volary"}, {"lat": 48.9210, "lng": 13.7930, "label": "Lenora"}, {"lat": 48.9040, "lng": 13.8270, "label": "Soumarský most"}, {"lat": 48.8580, "lng": 13.8280, "label": "Stožec"}, {"lat": 48.7920, "lng": 13.9370, "label": "Nová Pec"}, {"lat": 48.7740, "lng": 13.8950, "label": "Jelení Vrchy"}, {"lat": 48.9090, "lng": 13.8870, "label": "Cíl: Volary"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9090,13.8870&destination=48.9090,13.8870&travelmode=driving&waypoints=48.9210,13.7930%7C48.9040,13.8270%7C48.8580,13.8280%7C48.7920,13.9370%7C48.7740,13.8950', 'https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%BD%20plavebn%C3%AD%20kan%C3%A1l.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lenora%2C%20rechle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Soumarsk%C3%BD%20most.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sto%C5%BEeck%C3%A1%20kaple.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A1%20Pec.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%BD%20plavebn%C3%AD%20kan%C3%A1l.jpg"}'::text[], '{"Lenora – rechle","Soumarský most a rašeliniště","Stožecká kaple","Nová Pec","Schwarzenberský plavební kanál (Jelení Vrchy)"}'::text[], '{"CZ"}'::text[], false, 2090, 'approved');

  -- Českobudějovická muzea a koněspřežka
  delete from public.routes where name = 'Českobudějovická muzea a koněspřežka' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Českobudějovická muzea a koněspřežka', 'Krátký okruh pro dny, kdy počasí nepřeje dálkám: nejstarší železnice kontinentální Evropy a budějovická muzea v jednom balíčku. Koněspřežná dráha z Budějovic do Lince vyjela už roku 1827 a její stopu dodnes značí strážní domky — jeden z nich je muzeem přímo ve městě a v Holkově u Velešína se dochovala přepřahací stanice. K tomu Jihočeské muzeum, motocyklová sbírka v renesanční Solnici na Piaristickém náměstí a Černá věž s výhledem na celé město. Jede se po nenáročných silnicích druhé třídy s běžným provozem. Celoroční trasa — většina zastávek funguje i mimo sezónu.', 'loop', 70, 135, 'easy',
     '[{"lat": 48.9745, "lng": 14.4743, "label": "Start: České Budějovice"}, {"lat": 48.9663, "lng": 14.4695, "label": "Strážní domek koněspřežky"}, {"lat": 48.9000, "lng": 14.4550, "label": "Kamenný Újezd"}, {"lat": 48.8335, "lng": 14.4595, "label": "Holkov"}, {"lat": 48.8300, "lng": 14.4900, "label": "Velešín"}, {"lat": 48.9745, "lng": 14.4743, "label": "Cíl: České Budějovice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9745,14.4743&destination=48.9745,14.4743&travelmode=driving&waypoints=48.9663,14.4695%7C48.9000,14.4550%7C48.8335,14.4595%7C48.8300,14.4900', 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cern%C3%A1%20v%C4%9B%C5%BE%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cern%C3%A1%20v%C4%9B%C5%BE%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jiho%C4%8Desk%C3%A9%20muzeum%20v%20%C4%8Cesk%C3%BDch%20Bud%C4%9Bjovic%C3%ADch.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%2C%20Solnice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kon%C4%9Bsp%C5%99e%C5%BEn%C3%AD%20dr%C3%A1ha%20%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%2C%20str%C3%A1%C5%BEn%C3%AD%20domek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Holkov%2C%20p%C5%99ep%C5%99ahac%C3%AD%20stanice%20kon%C4%9Bsp%C5%99e%C5%BEky.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerna%20vez.jpg"}'::text[], '{"Náměstí Přemysla Otakara II. a Černá věž","Jihočeské muzeum","Jihočeské motocyklové muzeum (Solnice)","Muzeum koněspřežky – strážní domek","Holkov – přepřahací stanice koněspřežky","Restaurace: Krajinská 27 (České Budějovice)"}'::text[], '{"CZ"}'::text[], false, 2100, 'approved');

end $$;
