  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Hluboká nad Vltavou', 'Bílý novogotický zámek po vzoru anglického Windsoru, nejnavštěvovanější v Česku. Ze zámecké terasy je krásný výhled do vltavské nivy a parkoviště pod zámkem zvládne i plně naložený stroj. Prohlídku stihnete za hodinu, procházku parkem za dvacet minut.', 49.0510, 14.4444, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hluboka%20castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hluboka%20castle.jpg"}'::text[], 0),
    (v_route, 'Lovecký zámek Ohrada', 'Barokní lovecký zámeček kousek pod Hlubokou, dnes muzeum lesnictví, myslivosti a rybářství. Tiché místo u Munického rybníka s výhledem na hlubocký zámek nad hladinou. Ideální krátká zastávka na protažení nohou hned na začátku okruhu.', 49.0430, 14.4396, 'https://commons.wikimedia.org/wiki/Special:FilePath/Loveck%C3%BD%20z%C3%A1mek%20Ohrada%20-%20pr%C5%AF%C4%8Del%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Loveck%C3%BD%20z%C3%A1mek%20Ohrada%20-%20pr%C5%AF%C4%8Del%C3%AD.jpg"}'::text[], 1),
    (v_route, 'Týn nad Vltavou – náměstí Míru', 'Malebné městečko na soutoku Vltavy a Lužnice s renesančními štíty na náměstí a nábřežní promenádou. Po klikaté okresce od Purkarce sem dojedete lesy prakticky bez provozu. Zaparkujte přímo na náměstí a dejte si kávu s výhledem na řeku.', 49.2235, 14.4208, 'https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%BDn%20nad%20Vltavou.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%BDn%20nad%20Vltavou.JPG"}'::text[], 2),
    (v_route, 'Zámek Mitrowicz (Koloděje nad Lužnicí)', 'Citlivě zrekonstruovaný barokní zámeček na břehu Lužnice, kulisa mnoha filmů a svateb. Areál s kaplí a zahradou je přístupný sezónně, i zvenku ale stojí za krátkou fotopauzu. Od Týna jsou to jen tři kilometry.', 49.2110, 14.4670, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Mitrowicz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Mitrowicz.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Masné krámy (České Budějovice)', 'Legendární budějovická pivnice v gotické tržnici pár kroků od náměstí Přemysla Otakara II. Poctivá česká kuchyně a dokonale ošetřený Budvar — důstojná tečka za okruhem. V sezóně počítejte s plno, rezervace se vyplatí.', 48.9750, 14.4712, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%20Samson-Brunnen%20159.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%20Samson-Brunnen%20159.jpg"}'::text[], 4);
  insert into public.routes
