  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Klášter Zlatá Koruna', 'Jeden z nejzachovalejších gotických klášterů ve střední Evropě, schovaný v meandru Vltavy. Založil ho Přemysl Otakar II. roku 1263 a dodnes dýchá klidem — mimo prohlídky projdete nádvoří zdarma. Sjezd z hlavní silnice je krátký a parkuje se přímo u areálu.', 48.8551, 14.3714, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20Zlat%C3%A1%20Koruna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20Zlat%C3%A1%20Koruna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zlata%20Koruna%20Monastery.jpg"}'::text[], 0),
    (v_route, 'Státní hrad a zámek Český Krumlov', 'Druhý největší hradní komplex v Česku s ikonickou malovanou věží nad meandrem Vltavy, srdce města zapsaného na seznamu UNESCO. Z hradebních teras a plášťového mostu jsou nejfotografovanější výhledy v jižních Čechách. Motorku nechte na záchytném parkovišti P1 a centrum projděte pěšky.', 48.8127, 14.3149, 'https://commons.wikimedia.org/wiki/Special:FilePath/St%C3%A1tn%C3%AD%20hrad%20a%20z%C3%A1mek%20%C4%8Cesk%C3%BD%20Krumlov.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/St%C3%A1tn%C3%AD%20hrad%20a%20z%C3%A1mek%20%C4%8Cesk%C3%BD%20Krumlov.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20%C4%8Cesk%C3%BD%20Krumlov%20in%202012.JPG"}'::text[], 1),
    (v_route, 'Restaurace: Krčma v Šatlavské ulici (Český Krumlov)', 'Vyhlášená středověká krčma v bývalé městské šatlavě — maso z otevřeného ohně, svíčky a klenby. Jedno z nejlépe hodnocených míst ve městě, v sezóně je nutná rezervace. Perfektní oběd v půlce okruhu, než se vydáte údolím na jih.', 48.8103, 14.3160, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20%C4%8Cesk%C3%BD%20Krumlov%20in%202012.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20%C4%8Cesk%C3%BD%20Krumlov%20in%202012.JPG"}'::text[], 2),
    (v_route, 'Hrad Rožmberk nad Vltavou', 'Rodový hrad pánů z Růže na skále vysoko nad vltavským meandrem. Příjezd po silnici 160 podél řeky je zážitek sám o sobě a od hradu se otevírá výhled na celé údolí. Legenda o Bílé paní tu má svůj domov.', 48.6539, 14.3660, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20rozmberk.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20rozmberk.JPG"}'::text[], 3),
    (v_route, 'Klášter Vyšší Brod', 'Cisterciácké opatství ze 13. století, domov Závišova kříže — jedné z nejcennějších zlatnických památek Evropy. Rozlehlý areál s gotickým kostelem a klášterním pivovarem leží hned u silnice před městečkem. Odtud už vede zpáteční cesta přes Kaplici svižnými oblouky k Budějovicím.', 48.6157, 14.3110, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20Vy%C5%A1%C5%A1%C3%AD%20Brod.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter%20Vy%C5%A1%C5%A1%C3%AD%20Brod.JPG"}'::text[], 4);
