  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Kratochvíle', 'Renesanční vodní letohrádek Viléma z Rožmberka, postavený italskými mistry jako vila uprostřed obory. Bílá stavba obklopená vodním příkopem a zahradou je nejčistší ukázkou italské renesance v Čechách. Leží kousek od Netolic na klidné okresce, parkování přímo u zdi areálu.', 49.0637, 14.1701, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Kratochvile.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Kratochvile.JPG"}'::text[], 0),
    (v_route, 'Poutní kostel Lomec', 'Barokní poutní kostel Jména Panny Marie na zalesněném návrší mezi Vodňany a Netolicemi. Unikátní centrální stavba s baldachýnovým oltářem po vzoru svatopetrského v Římě, kolem ticho a vzrostlé lípy. Krátká odbočka po úzké lesní silničce stojí za to.', 49.1010, 14.2078, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lomec%2C%20kostel%20Jm%C3%A9na%20Panny%20Marie.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lomec%2C%20kostel%20Jm%C3%A9na%20Panny%20Marie.jpg"}'::text[], 1),
    (v_route, 'Bavorov – zámek a kostel', 'Ospalé městečko pod Helfenburkem s renesančním zámkem Rožmberků a mohutným gotickým kostelem Nanebevzetí Panny Marie. Dobré místo na doplnění paliva a kávu na náměstí, než se pustíte do lesních serpentin k hradu. Okreska z Bavorova na Helfenburk patří k nejhezčím v okolí.', 49.1220, 14.0787, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bavorov%20z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bavorov%20z%C3%A1mek.jpg"}'::text[], 2),
    (v_route, 'Zřícenina hradu Helfenburk u Bavorova', 'Rozsáhlá zřícenina rožmberského hradu ze 14. století ukrytá v hlubokých lesích. Z upravené vyhlídkové věže je kruhový rozhled od Šumavy po Písecké hory. Od lesního parkoviště počítejte s dvacetiminutovou procházkou do kopce.', 49.1367, 14.0064, 'https://commons.wikimedia.org/wiki/Special:FilePath/Helfenburk%2C%20obytn%C3%A1%20v%C4%9B%C5%BE%2C%20vstupn%C3%AD%20%C4%8D%C3%A1st.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Helfenburk%2C%20obytn%C3%A1%20v%C4%9B%C5%BE%2C%20vstupn%C3%AD%20%C4%8D%C3%A1st.jpg"}'::text[], 3),
    (v_route, 'Prachatice – Velké náměstí', 'Renesanční město, které zbohatlo na solné Zlaté stezce — sgrafitové fasády Velkého náměstí patří k nejkrásnějším v zemi. Zachovalé hradby, Písecká brána a desítky měšťanských domů s výmalbou. Zaparkujte před hradbami a projděte historické jádro pěšky, zabere to půl hodiny.', 49.0119, 13.9975, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prachatice%2C%20Velk%C3%A9%20n%C3%A1m%C4%9Bst%C3%AD%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prachatice%2C%20Velk%C3%A9%20n%C3%A1m%C4%9Bst%C3%AD%20(1).jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hráz Lipna a vodní elektrárna', 'Přes 280 metrů dlouhá hráz jihočeského moře s podzemní elektrárnou vytesanou 160 metrů hluboko v žule. Ze silnice vedoucí po koruně hráze je výhled na celé jezero i do údolí Vltavy pod ním. Hned vedle začíná kaskáda Čertových proudů.', 48.6270, 14.2390, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lipno%20nad%20Vltavou%2C%20p%C5%99ehradn%C3%AD%20hr%C3%A1z%2C%20p%C5%99ehrada.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lipno%20nad%20Vltavou%2C%20p%C5%99ehradn%C3%AD%20hr%C3%A1z%2C%20p%C5%99ehrada.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lipno%20nad%20Vltavou%2C%20p%C5%99ehradn%C3%AD%20hr%C3%A1z%2C%20elektr%C3%A1rna.JPG"}'::text[], 0),
    (v_route, 'NPR Čertova stěna-Luč', 'Národní přírodní rezervace s obřím žulovým kamenným mořem padajícím do údolí Vltavy — podle pověsti dílo samotného čerta. Vyhlídka na skalní srub je pár minut chůze od parkoviště u silnice Loučovice–Vyšší Brod. Divoké Čertovy proudy pod stěnou inspirovaly Smetanu i Wagnera.', 48.6210, 14.2860, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Certova-st%C4%9Bna-Vyhl%C3%ADdka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Certova-st%C4%9Bna-Vyhl%C3%ADdka.jpg"}'::text[], 1),
    (v_route, 'Vítkův hrádek (Svatý Tomáš)', 'Nejvýše položený hrad v Čechách (1035 m) nad osadou Svatý Tomáš. Z opravené obytné věže je za dobré viditelnosti vidět celé Lipno, Šumava i řetěz Alp na obzoru. Poslední kilometr se jde pěšky lesem, motorku necháte na parkovišti u osady.', 48.6297, 14.1935, 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADtk%C5%AFv%20k%C3%A1men%2Cz%C5%99icenina.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADtk%C5%AFv%20k%C3%A1men%2Cz%C5%99icenina.JPG"}'::text[], 2),
    (v_route, 'Frymburk a přívoz do Frýdavy', 'Malebné městečko na poloostrově s dlouhou návsí, gotickým kostelem a promenádou u vody. Přes jezero odtud jezdí legendární přívoz do Frýdavy, který převeze i motorku — zkratka na pravý břeh a malé dobrodružství k tomu. Ideální místo na zmrzlinu s výhledem na hladinu.', 48.6592, 14.1657, 'https://commons.wikimedia.org/wiki/Special:FilePath/Frymburk%2C%20p%C5%99%C3%ADvoz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Frymburk%2C%20p%C5%99%C3%ADvoz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Frymburk%2C%20kostel%20a%20fara.jpg"}'::text[], 3),
    (v_route, 'Horní Planá – rodiště Adalberta Stiftera', 'Městečko na levém břehu Lipna, rodiště šumavského básníka Adalberta Stiftera — jeho rodný dům je dnes památník a nad městem stojí spisovatelova socha s výhledem na jezero. Náměstí s podloubím zve na kávu, pláž u přívozu na krátkou pauzu u vody.', 48.7683, 14.0326, 'https://commons.wikimedia.org/wiki/Special:FilePath/A%20Stifter-statue.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/A%20Stifter-statue.JPG"}'::text[], 4),
    (v_route, 'Restaurace: Hotel Maxant (Frymburk)', 'Rodinný hotel s vyhlášenou restaurací přímo na frymburské návsi, pár kroků od vody. Poctivá jihočeská kuchyně, ryby z Lipna a domácí dezerty — nejjistější oběd na celém okruhu. V létě příjemná zahrádka s výhledem na kostel.', 48.6597, 14.1650, 'https://commons.wikimedia.org/wiki/Special:FilePath/Frymburk%2C%20kostel%20a%20fara.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Frymburk%2C%20kostel%20a%20fara.jpg"}'::text[], 5);
