  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vodní nádrž Římov', 'Přehrada na Malši ze sedmdesátých let zásobuje pitnou vodou většinu jižních Čech. Sypaná hráz vysoká 47 metrů je vidět z vyhlídky nad údolím; samotná nádrž je jako vodárenská chráněná, o to divočejší je okolní příroda. Kolem vede příjemná okreska s minimem aut.', 48.8486, 14.4897, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%98%C3%ADmov%2C%20vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%98%C3%ADmov%2C%20pohled%20k%20hr%C3%A1zi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%98%C3%ADmov%2C%20vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%98%C3%ADmov%2C%20pohled%20k%20hr%C3%A1zi.jpg"}'::text[], 0),
    (v_route, 'Římov – Loreta a pašijová cesta', 'Barokní poutní areál s loretánskou kaplí a unikátní pašijovou cestou s 25 zastaveními, která obchází vesnici jako malý jeruzalémský okruh. Ambity zdobí fresky a areál je volně přístupný. Klidné místo na protažení po prvních kilometrech.', 48.8563, 14.4855, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%98%C3%ADmov%2C%20Loreta%203.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%98%C3%ADmov%2C%20Loreta%203.JPG"}'::text[], 1),
    (v_route, 'Trocnov – památník Jana Žižky', 'Rodiště nejslavnějšího husitského vojevůdce s monumentální žulovou sochou, muzeem a nově i archeoskanzenem středověké vesnice. Areál v lesích u Borovan je příjemnou zastávkou s dostatkem parkování. Expozice zabere půl hodiny, skanzen o něco víc.', 48.8980, 14.5990, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jan%20%C5%BDi%C5%BEka%20z%20Trocnova%20(03).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jan%20%C5%BDi%C5%BEka%20z%20Trocnova%20(03).JPG"}'::text[], 2),
    (v_route, 'Vodní nádrž Hněvkovice – hráz', 'Přehrada vltavské kaskády postavená v osmdesátých letech jako zdroj chladicí vody pro Temelín. Betonová hráz s mostovkou nabízí výhled na jezero rámované lesy; pod hrází pokračuje Vltava k Týnu. Silnice po hrázi spojuje oba břehy a je volně průjezdná.', 49.1830, 14.4470, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Hn%C4%9Bvkovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Hn%C4%9Bvkovice.jpg"}'::text[], 3),
    (v_route, 'Infocentrum JE Temelín – zámeček Vysoký Hrádek', 'Návštěvnické centrum největší české elektrárny sídlí v renesančním zámečku Vysoký Hrádek přímo u areálu. Interaktivní expozice o jaderné energetice je zdarma a z parku je nejlepší pohled na čtveřici 155metrových chladicích věží. Technika, která bere dech i z motorkářského sedla.', 49.1770, 14.3690, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chlad%C3%ADc%C3%AD%20v%C4%9B%C5%BEe%20JETE.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chlad%C3%ADc%C3%AD%20v%C4%9B%C5%BEe%20JETE.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Holašovice – selské baroko (UNESCO)', 'Dokonale dochovaná jihočeská náves obklopená štíty selského baroka, od roku 1998 na seznamu UNESCO. Dvaadvacet usedlostí kolem rybníčku s kapličkou vypadá jako kulisa, ale žije se tu normálně dál. Zastavte na parkovišti před vsí a projděte náves pěšky.', 48.9700, 14.2726, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hola%C5%A1ovice%20Historic%20Village-112772.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hola%C5%A1ovice%20Historic%20Village-112772.jpg"}'::text[], 0),
    (v_route, 'Rozhledna Kleť', 'Nejstarší kamenná rozhledna v Čechách (1825) na nejvyšším vrcholu Blanského lesa (1084 m). Za dobré viditelnosti dohlédnete přes Šumavu až na zasněžené vrcholy Alp vzdálené přes 150 kilometrů. Hned vedle stojí známá hvězdárna, která objevila stovky planetek.', 48.8645, 14.2834, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Kle%C5%A5%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Kle%C5%A5%201.JPG"}'::text[], 1),
    (v_route, 'Lanová dráha Krasetín–Kleť', 'Nejstarší sedačková lanovka v Česku (1961) vyveze líné i unavené z Krasetína na vrchol Kleti za čtvrt hodiny. Motorku pohodlně necháte na parkovišti u dolní stanice. Kdo chce, může nahoru pěšky lesem — nahoře čeká chata s výčepem a terasou.', 48.8800, 14.3050, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kle%C5%A5%20lanovka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kle%C5%A5%20lanovka.jpg"}'::text[], 2),
    (v_route, 'Zřícenina hradu Dívčí Kámen', 'Jedna z největších hradních zřícenin v Čechách na skalnatém ostrohu nad soutokem Vltavy a Křemžského potoka. Rožmberský hrad ze 14. století je opředený pověstmi a obklopený přírodní rezervací. Od parkoviště v Třísově je to příjemných dvacet minut pěšky.', 48.8888, 14.3630, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20D%C3%ADv%C4%8D%C3%AD%20K%C3%A1men%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20D%C3%ADv%C4%8D%C3%AD%20K%C3%A1men%202.jpg"}'::text[], 3),
    (v_route, 'Kuklov – zřícenina kláštera', 'Nedostavěný pavlánský klášter z 15. století srostlý se stavením vesničky Kuklov — gotické zdi kostela stojí přímo mezi chalupami. Málo známé, o to působivější místo na dohled od Kleti. Krátká odbočka z Brloha po úzké silničce.', 48.9390, 14.2050, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kuklov%2C%20z%C5%99%C3%ADcenina%20kl%C3%A1%C5%A1tera.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kuklov%2C%20z%C5%99%C3%ADcenina%20kl%C3%A1%C5%A1tera.jpg"}'::text[], 4);
