  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Písek – Kamenný most', 'Nejstarší dochovaný kamenný most v Česku, o generaci starší než pražský Karlův. Gotický most přes Otavu z 13. století je dnes pěší zónou s barokními sochami a výhledem na nábřeží. Zaparkujte na nábřeží a projděte si i blízké Velké náměstí.', 49.3088, 14.1469, 'https://commons.wikimedia.org/wiki/Special:FilePath/P%C3%ADsek%2C%20kamenn%C3%BD%20most.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/P%C3%ADsek%2C%20kamenn%C3%BD%20most.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/P%C3%ADsek%2C%20the%20Stone%20Bridge-2.JPG"}'::text[], 0),
    (v_route, 'Rozhledna Jarník', 'Šedesátimetrová věž na kopci Jarník dva kilometry od Písku, kombinace rozhledny a vysílače. Z ochozu ve výšce 30 metrů přehlédnete Otavu, Písecké hory a za dobrého počasí i šumavské hřebeny. Přístup po zpevněné lesní cestě až k patě věže.', 49.3006, 14.1934, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Jarn%C3%ADk%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Jarn%C3%ADk%20(1).JPG"}'::text[], 1),
    (v_route, 'Rozhledna Velký Kamýk', 'Dřevěná rozhledna na nejvyšším bodě Píseckých hor (627 m) uprostřed hlubokých lesů. Tiché místo, kam trefí jen málokdo — výhled na Otavskou nivu, Temelín i Šumavu. Od lesního parkoviště pár minut pěšky po hřebeni.', 49.2758, 14.2040, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Velk%C3%BD%20Kam%C3%BDk.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Velk%C3%BD%20Kam%C3%BDk.JPG"}'::text[], 2),
    (v_route, 'Zemský hřebčinec Písek', 'Secesní areál zemského hřebčince z roku 1902, národní kulturní památka a dodnes fungující chov plemenných hřebců. Monumentální stáje s věžičkami připomínají spíš zámek než hospodářský dvůr. Prohlídky v návštěvních hodinách, zvenku volně k vidění.', 49.3149, 14.1360, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zemsk%C3%BD%20h%C5%99eb%C4%8Dinec%20P%C3%ADsek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zemsk%C3%BD%20h%C5%99eb%C4%8Dinec%20P%C3%ADsek.jpg"}'::text[], 3),
    (v_route, 'Restaurace: U Reinerů (Písek)', 'Tradiční měšťanská restaurace na Velkém náměstí, píseckou klasiku tu vaří už desítky let. Poctivé polední menu, jihočeské ryby i pivo z místního minipivovaru. Po okruhu ideální místo na pozdní oběd dvě minuty chůze od Kamenného mostu.', 49.3084, 14.1475, 'https://commons.wikimedia.org/wiki/Special:FilePath/P%C3%ADsek%2C%20the%20Stone%20Bridge-2.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/P%C3%ADsek%2C%20the%20Stone%20Bridge-2.JPG"}'::text[], 4);
  insert into public.routes
