  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Nové Hrady', 'Gotický hrad ze 13. století obklopený nejhlubším suchým příkopem v Čechách. Strážil zemskou stezku do Rakouska a dodnes vévodí náměstíčku pohraničního městečka s buquoyskou rezidencí a klášterem. Prohlídka zabere hodinu, výhled z valů je zdarma.', 48.7896, 14.7786, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Nov%C3%A9%20Hrady.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Nov%C3%A9%20Hrady.jpg"}'::text[], 0),
    (v_route, 'Terčino údolí – umělý vodopád', 'Romantický krajinný park z 18. století, který nechala založit hraběnka Terezie Buquoyová v údolí Stropnice. Procházka kolem Modrého domu a lázniček vede k umělému vodopádu napájenému náhonem — nejfotogeničtějšímu místu parku. Od parkoviště u vstupu počítejte s půlhodinovou procházkou.', 48.7830, 14.7560, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tercino-udoli-vodopad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tercino-udoli-vodopad.jpg"}'::text[], 1),
    (v_route, 'Tvrz Cuknštejn', 'Pozdně gotická tvrz z konce 15. století na okraji Terčina údolí, jedna z nejzachovalejších v Čechách. Kamenný čtyřkřídlý objekt s věží prošel citlivou obnovou a hraje ve filmech i seriálech. Stojí přímo u cesty do údolí — fotka bez sesedání.', 48.7770, 14.7620, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20Hrady%2C%20%C3%9Adol%C3%AD%2C%20Cukn%C5%A1tejn%20(01).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20Hrady%2C%20%C3%9Adol%C3%AD%2C%20Cukn%C5%A1tejn%20(01).jpg"}'::text[], 2),
    (v_route, 'Dobrá Voda u Nových Hradů', 'Barokní poutní kostel Nanebevzetí Panny Marie přilepený na svahu pod Kraví horou, se zázračným pramenem a výhledem do rakouského podhůří. Bílé průčelí září do kraje na desítky kilometrů. Serpentiny z Horní Stropnice nahoru jsou krátké, ale šťavnaté.', 48.7423, 14.7290, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dobr%C3%A1%20voda%20kostel%204.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dobr%C3%A1%20voda%20kostel%204.jpg"}'::text[], 3),
    (v_route, 'Rozhledna Kraví hora', 'Kamenno-dřevěná rozhledna na žulovém vrcholu Kraví hory (953 m) nad Hojnou Vodou. Výhled na celé Novohradské hory, Lipno i alpské vrcholy na jihu; kolem vrcholu bizarní žulové skalní útvary. Z parkoviště v Hojné Vodě nahoru zhruba půl hodiny pěšky.', 48.7280, 14.7220, 'https://commons.wikimedia.org/wiki/Special:FilePath/Krav%C3%AD%20hora%20rozhledna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Krav%C3%AD%20hora%20rozhledna.jpg"}'::text[], 4),
    (v_route, 'Pohoří na Šumavě – zaniklá osada', 'Kdysi živé pohraniční městečko, po roce 1955 srovnané se zemí — zůstal jen obnovovaný kostel Panny Marie Dobré Rady a pár chalup uprostřed luk. Jedno z nejmelancholičtějších míst Čech, na dohled od rakouské hranice. Poslední kilometry vedou po úzké silničce zaniklou krajinou, jeďte opatrně.', 48.6000, 14.6940, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poho%C5%99%C3%AD%20na%20%C5%A0umav%C4%9B.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poho%C5%99%C3%AD%20na%20%C5%A0umav%C4%9B.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lenora – rechle', 'Krytý dřevěný most přes Teplou Vltavu, kterým se kdysi hradilo plavené dříví — poslední svého druhu na Šumavě. Sklářská obec Lenora nabízí i historickou obecní pec, kde se o víkendech peče chleba. Fotogenická zastávka hned u silnice.', 48.9210, 13.7930, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lenora%2C%20rechle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lenora%2C%20rechle.jpg"}'::text[], 0),
    (v_route, 'Soumarský most a rašeliniště', 'Vrchovištní rašeliniště v nivě Teplé Vltavy s naučnou stezkou po povalovém chodníku a vyhlídkovou věží nad meandry řeky. Místo, kudy soumaři po Zlaté stezce brodili náklady soli. Půlhodinový okruh pěšky od parkoviště u mostu.', 48.9040, 13.8270, 'https://commons.wikimedia.org/wiki/Special:FilePath/Soumarsk%C3%BD%20most.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Soumarsk%C3%BD%20most.jpg"}'::text[], 1),
    (v_route, 'Stožecká kaple', 'Dřevěná poutní kaple z roku 1791 přilepená pod skalní stěnou nad osadou Stožec, symbol smíření na česko-bavorském pomezí. Od parkoviště ve Stožci vede nahoru pohodlná lesní cesta, tam a zpět hodina chůze. Odměnou je ticho horského lesa a pramen s údajně léčivou vodou.', 48.8650, 13.8210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sto%C5%BEeck%C3%A1%20kaple.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sto%C5%BEeck%C3%A1%20kaple.JPG"}'::text[], 2),
    (v_route, 'Nová Pec', 'Horská obec na horním konci Lipna, kde jezero přechází v divokou Vltavu a nad krajinou se zvedá hraniční hřeben s Plechým, nejvyšší horou české Šumavy. Poslední občerstvení a palivo před odbočkou k Jelením Vrchům. Od nádraží pěkný výhled na Trojmezenskou hornatinu.', 48.7920, 13.9370, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A1%20Pec.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A1%20Pec.jpg"}'::text[], 3),
    (v_route, 'Schwarzenberský plavební kanál (Jelení Vrchy)', 'Technický div z konce 18. století: 44 kilometrů dlouhý kanál, který plavil šumavské dřevo přes evropské rozvodí až do Vídně. U osady Jelení Vrchy vtéká do 400 metrů dlouhého plavebního tunelu; v létě se tu konají ukázky plavení dříví. Silnička z Nové Pece končí parkovištěm přímo u kanálu.', 48.7740, 13.8950, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%BD%20plavebn%C3%AD%20kan%C3%A1l.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%BD%20plavebn%C3%AD%20kan%C3%A1l.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Náměstí Přemysla Otakara II. a Černá věž', 'Jedno z největších čtvercových náměstí v Evropě se Samsonovou kašnou a podloubím ze všech stran. Z ochozu 72 metrů vysoké Černé věže je celé město i Kleť jako na dlani — 225 schodů stojí za to. Parkování v modrých zónách kolem centra nebo v domě u Dlouhé louky.', 48.9745, 14.4743, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cern%C3%A1%20v%C4%9B%C5%BE%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cern%C3%A1%20v%C4%9B%C5%BE%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%20Samson-Brunnen%20159.jpg"}'::text[], 0),
    (v_route, 'Jihočeské muzeum', 'Nejstarší a největší muzeum v jižních Čechách v honosné novorenesanční budově z roku 1903. Stálé expozice přírody i historie regionu a především unikátní sbírka ke koněspřežní dráze Budějovice–Linec. Ideální start okruhu — vše ostatní dává po návštěvě větší smysl.', 48.9718, 14.4767, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jiho%C4%8Desk%C3%A9%20muzeum%20v%20%C4%8Cesk%C3%BDch%20Bud%C4%9Bjovic%C3%ADch.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jiho%C4%8Desk%C3%A9%20muzeum%20v%20%C4%8Cesk%C3%BDch%20Bud%C4%9Bjovic%C3%ADch.jpg"}'::text[], 1),
    (v_route, 'Jihočeské motocyklové muzeum (Solnice)', 'Sbírka více než stovky historických motocyklů — Jawy, ČZ, Laurin & Klement i váleční veteráni — v gotické Solnici na Piaristickém náměstí. Povinná zastávka každého motorkáře: stroje, vůně benzínu a příběhy československého motocyklismu. Otevřeno v sezóně denně.', 48.9748, 14.4712, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%2C%20Solnice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%2C%20Solnice.jpg"}'::text[], 2),
    (v_route, 'Muzeum koněspřežky – strážní domek', 'Expozice v původním strážním domku č. 1 v Mánesově ulici připomíná první železnici kontinentální Evropy, po níž koně tahali vagóny se solí do Lince. Malé, ale poctivé muzeum s modely a dobovými plány. Odtud vyrazíte přesně po stopě staré dráhy na jih.', 48.9663, 14.4695, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kon%C4%9Bsp%C5%99e%C5%BEn%C3%AD%20dr%C3%A1ha%20%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%2C%20str%C3%A1%C5%BEn%C3%AD%20domek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kon%C4%9Bsp%C5%99e%C5%BEn%C3%AD%20dr%C3%A1ha%20%C4%8Cesk%C3%A9%20Bud%C4%9Bjovice%2C%20str%C3%A1%C5%BEn%C3%AD%20domek.jpg"}'::text[], 3),
    (v_route, 'Holkov – přepřahací stanice koněspřežky', 'Nejzachovalejší přepřahací stanice koněspřežní dráhy s formanskou hospodou a stájemi, kde se měnila spřežení na trase do Lince. Areál u Velešína stojí přímo u staré císařské silnice; násep dráhy je v terénu dodnes čitelný. Kousek odtud se klikatí hezká okreska zpět k Budějovicím podél Malše.', 48.8335, 14.4595, 'https://commons.wikimedia.org/wiki/Special:FilePath/Holkov%2C%20p%C5%99ep%C5%99ahac%C3%AD%20stanice%20kon%C4%9Bsp%C5%99e%C5%BEky.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Holkov%2C%20p%C5%99ep%C5%99ahac%C3%AD%20stanice%20kon%C4%9Bsp%C5%99e%C5%BEky.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Krajinská 27 (České Budějovice)', 'Řemeslný minipivovar s výborně hodnocenou restaurací v historickém domě v Krajinské ulici. Vlastní nefiltrovaná piva, burgery i česká klasika z lokálních surovin. Dvě minuty od náměstí — perfektní zakončení městského okruhu.', 48.9761, 14.4726, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cerna%20vez.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cerna%20vez.jpg"}'::text[], 5);
